/* SPDX-License-Identifier: GPL-3.0-only */
/* Send reverb, synced delay and master stage: a port of 9W9's er99_verb_tick,
 * er99_dly_tick, master distortion and master_glue (GPL-3.0). See fxbus.h. */
#include "fxbus.h"
#include "../x0x_cold.h"          /* X0X_COLD: fxbus_init is boot only, not the send/render */

static const int32_t fx_cl[4] = { 1116, 1188, 1277, 1356 };
static const int32_t fx_al[2] = { 556, 441 };
static const int32_t fx_alr[2] = { 579, 457 };
#define FX_RV_QUIET (1356 + 8192)          /* combs silent this long: the allpass tail is < -140 dB */

/* 1/32 1/16T 1/16 1/8T 1/16. 1/8 1/4T 1/8. 1/4 1/2T 1/4. 1/2 1/2. (in beats) */
static const float fx_beats[13] = {
    0.125f, 1.0f / 6.0f, 0.25f, 1.0f / 3.0f, 0.375f, 0.5f, 2.0f / 3.0f,
    0.75f, 1.0f, 4.0f / 3.0f, 1.5f, 2.0f, 3.0f
};

/* ---- parameters ---- */
enum { CV_LIN, CV_EXP, CV_SW };
typedef struct {
    x0x_param_t ui;
    uint8_t curve, exp;
    float lo, hi;
} fx_pspec_t;

static const char *const fx_div_names[13] = {
    "1/32", "1/16T", "1/16", "1/8T", "1/16.", "1/8", "1/4T", "1/8.", "1/4", "1/2T", "1/4.", "1/2", "1/2."
};
static const char *const fx_type_names[2] = { "DIGI", "TAPE" };
static const char *const fx_onoff_names[2] = { "OFF", "ON" };

/* pot defaults: the positions 9W9 seeds from its defaults (the engine itself
 * starts on the exact defaults) */
static const fx_pspec_t fx_p[FX_NPARAMS] = {
    [FX_VOLUME]   = { { "Volume", 127, 44, 0 }, CV_LIN, 0, 0.0f, 1.0f },
    [FX_DIST]     = { { "Dist", 7, 0, x0x_dist_names }, CV_SW, 0, 0.0f, 0.0f },
    [FX_DRIVE]    = { { "Drive", 127, 41, 0 }, CV_EXP, X0X_EXP_DRIVE, 0.0f, 0.0f },
    [FX_COMP]     = { { "Comp", 127, 0, 0 }, CV_LIN, 0, 0.0f, 1.0f },
    [FX_RV_DECAY] = { { "RvDec", 127, 73, 0 }, CV_LIN, 0, 0.2f, 0.93f },
    [FX_RV_TONE]  = { { "RvTone", 127, 57, 0 }, CV_LIN, 0, 0.0f, 1.0f },
    [FX_RV_HPF]   = { { "RvHPF", 127, 62, 0 }, CV_EXP, X0X_EXP_FX_HPF, 0.0f, 0.0f },
    [FX_RV_LEVEL] = { { "RvLvl", 127, 85, 0 }, CV_LIN, 0, 0.0f, 1.2f },
    [FX_DL_TIME]  = { { "DlTime", 12, 7, fx_div_names }, CV_SW, 0, 0.0f, 0.0f },
    [FX_DL_FDBK]  = { { "DlFdbk", 127, 52, 0 }, CV_LIN, 0, 0.0f, 0.85f },
    [FX_DL_TONE]  = { { "DlTone", 127, 51, 0 }, CV_LIN, 0, 0.0f, 1.0f },
    [FX_DL_LEVEL] = { { "DlLvl", 127, 85, 0 }, CV_LIN, 0, 0.0f, 1.2f },
    [FX_DL_HPF]   = { { "DlHPF", 127, 62, 0 }, CV_EXP, X0X_EXP_FX_HPF, 0.0f, 0.0f },
    [FX_DL_TYPE]  = { { "DlType", 1, 0, fx_type_names }, CV_SW, 0, 0.0f, 0.0f },
    [FX_DL_WEAR]  = { { "Wear", 127, 64, 0 }, CV_LIN, 0, 0.0f, 1.0f },
    [FX_DL_PING]  = { { "Ping", 1, 0, fx_onoff_names }, CV_SW, 0, 0.0f, 0.0f },
};

int fxbus_nparams(void) { return FX_NPARAMS; }

const x0x_param_t *fxbus_param(int i)
{
    return i >= 0 && i < FX_NPARAMS ? &fx_p[i].ui : 0;
}

int fxbus_get(const fxbus_t *f, int i)
{
    return i >= 0 && i < FX_NPARAMS ? f->pots[i] : 0;
}

__attribute__((noinline)) static void fx_retime(fxbus_t *f)
{
    int32_t i = f->dl_div;
    if (i < 0) i = 0;
    if (i > 12) i = 12;
    const float bpm = f->bpm >= 20.0f ? f->bpm : 120.0f;
    float ms = fx_beats[i] * 60000.0f / bpm;
    const float max_ms = (float)(f->dlen - 256) / D9_SR * 1000.0f;
    while (ms > max_ms)                 /* longer than the line (1/2. under 90 BPM): half of it, */
        ms *= 0.5f;                     /* which is still on the beat; cutting it short is not */
    f->dl_time_ms = ms;
}

/* Pot/init path only — not the send/render (X0X_COLD) */
X0X_COLD static void fx_comp_prep(fxbus_t *f)
{
    const float a = f->comp;
    const float ratio = 2.0f + 3.0f * a;
    f->c_thr = 10.0f - 18.0f * a;
    f->c_slope = 1.0f - 1.0f / ratio;
    f->c_makeup = a * 2.2f + a * a * 6.6f;
}

/* Pot path only — not the send/render (X0X_COLD) */
X0X_COLD static void fx_apply(fxbus_t *f, int i, float v)
{
    switch (i) {
    case FX_VOLUME: f->volume = v; break;
    case FX_DIST: f->dist_mode = (int32_t)v; break;
    case FX_DRIVE: f->drive = v; break;
    case FX_COMP: f->comp = v < 0.0f ? 0.0f : (v > 1.0f ? 1.0f : v); fx_comp_prep(f); break;
    case FX_RV_DECAY: f->rv_decay = v; break;
    case FX_RV_TONE: f->rv_tone = v; break;
    case FX_RV_HPF: d9_biquad_set(&f->rv_hp, D9_HP, v, 0.7071f); break;
    case FX_RV_LEVEL: f->rv_level = v; break;
    case FX_DL_TIME: f->dl_div = (int32_t)v; fx_retime(f); break;
    case FX_DL_FDBK: f->dl_fdbk = v; break;
    case FX_DL_TONE: f->dl_tone = v; break;
    case FX_DL_LEVEL: f->dl_level = v; break;
    case FX_DL_HPF: d9_biquad_set(&f->dl_hp, D9_HP, v, 0.7071f); break;
    case FX_DL_TYPE: f->dl_type = (int32_t)v; break;
    case FX_DL_WEAR: f->wear = v; break;
    case FX_DL_PING: f->dl_ping = (int32_t)v; break;
    default: break;
    }
    if (i == FX_DIST || i == FX_DRIVE)
        d9_shape_prep(&f->shape, f->drive, f->dist_mode - 1);
}

/* UI/MIDI pot path — not the send/render (X0X_COLD) */
X0X_COLD void fxbus_set(fxbus_t *f, int i, int value)
{
    if (i < 0 || i >= FX_NPARAMS)
        return;
    const fx_pspec_t *s = &fx_p[i];
    if (value < 0) value = 0;
    if (value > s->ui.max) value = s->ui.max;
    f->pots[i] = (uint8_t)value;
    float v;
    if (s->curve == CV_EXP)
        v = x0x_pot_exp_value(s->exp, value);
    else if (s->curve == CV_SW)
        v = (float)value;
    else
        v = s->lo + (s->hi - s->lo) * ((float)value / 127.0f);
    fx_apply(f, i, v);
}

void fxbus_set_bpm(fxbus_t *f, float bpm)
{
    if (bpm >= 20.0f && bpm != f->bpm) {
        f->bpm = bpm;
        fx_retime(f);
    }
}

/* Boot only (engine_init). fxbus_process and the reverb/delay ticks stay -O2. */
X0X_COLD void fxbus_init(fxbus_t *f, int16_t *dly_buf, int dly_len)
{
    uint8_t *p = (uint8_t *)f;
    for (unsigned i = 0; i < sizeof(*f); ++i)
        p[i] = 0;
    for (int i = 0; i < dly_len; ++i)
        dly_buf[i] = 0;
    f->dbuf = dly_buf;
    f->dlen = dly_len;

    f->rv_decay = 0.62f; f->rv_tone = 0.45f; f->rv_level = 0.8f;
    d9_biquad_set(&f->rv_hp, D9_HP, 150.0f, 0.7071f);
    f->rv_quiet = FX_RV_QUIET;

    f->dl_div = 7;
    f->bpm = 120.0f;
    f->dl_fdbk = 0.35f; f->dl_tone = 0.4f; f->dl_level = 0.8f;
    fx_retime(f);
    f->dcur = f->dl_time_ms * 0.001f * D9_SR;
    d9_biquad_set(&f->dl_hp, D9_HP, 150.0f, 0.7071f);
    f->dl_quiet = dly_len;
    f->dl_type = 0;
    f->wear = 64.0f / 127.0f;

    f->comp = 0.0f;
    f->drive = 2.0f;
    f->dist_mode = 0;
    f->volume = 0.35f;
    d9_shape_prep(&f->shape, f->drive, -1);
    fx_comp_prep(f);
    f->c_drel = d9_exp_small(-1.0f / (0.035f * D9_SR));
    f->c_atk = d9_exp_small(-1.0f / (0.003f * D9_SR));
    f->c_rel = d9_exp_small(-1.0f / (0.120f * D9_SR));

    for (int i = 0; i < FX_NPARAMS; ++i)
        f->pots[i] = fx_p[i].ui.def;
}


/* 12-bit sat store (toward zero). Shared by reverb combs + delay DIGI/TAPE writes. */
__attribute__((noinline)) static int32_t sat12_store(int16_t *cell, float v)
{
    int32_t k = (int32_t)(v * 2048.0f);
    if (k > 32767) k = 32767;
    if (k < -32767) k = -32767;
    *cell = (int16_t)k;
    return k;
}

/* Distortion sample — one body; stereo process_st calls this for L and R. */
__attribute__((noinline)) static float dist_one(const d9_shape_t *sh, float x, float k, float *crush)
{
    return d9_shape(sh, x * k, crush) * 0.7f;
}

/* One Schroeder allpass step — shared by L/R reverb (mono 2×, stereo 4×). */
__attribute__((noinline)) static float rv_ap(float *ab, int32_t *pos, int32_t alen, float y)
{
    const int32_t p = *pos;
    const float bo = ab[p];
    ab[p] = y + bo * 0.5f;
    *pos = p + 1 >= alen ? 0 : p + 1;
    return bo - y * 0.5f;
}

/* One Schroeder comb step — shared across 4 combs (pi32: beats unrolled copies). */
__attribute__((noinline)) static float rv_comb(fxbus_t *f, int16_t *b, int c, float x, float damp, float fb, int32_t *wr)
{
    const int32_t p = f->cpos[c];
    const float y = (float)b[p] * (1.0f / 2048.0f);
    f->cdmp[c] = y + (f->cdmp[c] - y) * damp;
    *wr |= sat12_store(&b[p], x + f->cdmp[c] * fb);
    f->cpos[c] = p + 1 >= fx_cl[c] ? 0 : p + 1;
    return y;
}

/* ===================================================================== */
/* Reverb (er99_verb_tick), adds its return into out                      */
/* ===================================================================== */
static void fx_reverb(fxbus_t *f, const float *in, float *out, float *out_r, int n)
{
    if (f->rv_quiet >= FX_RV_QUIET) {
        int any = 0;
        for (int i = 0; i < n; ++i)
            any |= in[i] != 0.0f;
        if (!any)
            return;                         /* silent in, silent lines: 0 out */
    }
    const float damp = 0.75f - f->rv_tone * 0.55f;
    const float fb = f->rv_decay;
    const float lvl = f->muted & 1u ? 0.0f : f->rv_level;
    int16_t *cb[4];
    cb[0] = f->comb;
    cb[1] = cb[0] + fx_cl[0];
    cb[2] = cb[1] + fx_cl[1];
    cb[3] = cb[2] + fx_cl[2];
    float *ab0 = f->ap, *ab1 = f->ap + fx_al[0];
    float *ar0 = f->apr, *ar1 = f->apr + fx_alr[0];
    int32_t quiet = f->rv_quiet;
    for (int i = 0; i < n; ++i) {
        const float x = d9_biquad_tick(&f->rv_hp, in[i]);
        float acc = 0.0f, acc_r = 0.0f;
        int32_t wr = 0;
        for (int c = 0; c < 4; ++c) {
            const float y = rv_comb(f, cb[c], c, x, damp, fb, &wr);
            acc += y;
            acc_r += (c & 1) ? -y : y;
        }
        float y = acc * 0.25f;
        y = rv_ap(ab0, &f->apos[0], fx_al[0], y);
        y = rv_ap(ab1, &f->apos[1], fx_al[1], y);
        out[i] += y * lvl;
        if (out_r) {                        /* the right: the combs, alternate signs, its own allpasses */
            float yr = acc_r * 0.25f;
            yr = rv_ap(ar0, &f->aposr[0], fx_alr[0], yr);
            yr = rv_ap(ar1, &f->aposr[1], fx_alr[1], yr);
            out_r[i] += yr * lvl;
        }
        quiet = (wr == 0 && in[i] == 0.0f) ? quiet + 1 : 0;
    }
    f->rv_quiet = quiet;
}

/* ===================================================================== */
/* Delay (er99_dly_tick), adds its return into out                        */
/* ===================================================================== */
__attribute__((noinline)) static float fx_psin(uint32_t ph)                 /* parabolic sine of a turn */
{
    const float x = (float)(int32_t)ph * (1.0f / 2147483648.0f);
    return 4.0f * x * (1.0f - fm_fabsf(x));
}

/* the line at d samples behind w, interpolated (X0X: the ping-pong tap).
 * Outlined once: fx_delay calls this many times (mono + stereo / PING taps);
 * one body beats N inlined copies on pi32 (-O2). */
__attribute__((noinline)) static float dl_tap(const int16_t *buf, int32_t len, float flen, int32_t w, float d)
{
    float rp = (float)w - d;
    while (rp < 0.0f) rp += flen;
    int32_t i0 = (int32_t)rp;
    const float fr = rp - (float)i0;
    if (i0 >= len) i0 -= len;
    const int32_t i1 = i0 + 1 >= len ? 0 : i0 + 1;
    const float b0 = (float)buf[i0] * (1.0f / 2048.0f), b1 = (float)buf[i1] * (1.0f / 2048.0f);
    return b0 + (b1 - b0) * fr;
}

/* out_r 0: 9W9's mono delay. Else both sides get the echo, or with PING the left reads at the time and
 * the right at twice it, the loop fed from the right: echoes alternate L R L R, one time apart. The
 * line holds both, so PING needs twice the time to fit (a 2 s line: 1 s); past that it plays centred. */
static void fx_delay(fxbus_t *f, const float *in, float *out, float *out_r, int n)
{
    f->dl_signal = 0;
    const float target = f->dl_time_ms * 0.001f * D9_SR;
    const int32_t len = f->dlen;
    const int tape = f->dl_type == 1;
    if (f->dl_quiet >= len) {
        int any = 0;
        for (int i = 0; i < n; ++i)
            any |= in[i] != 0.0f;
        if (!any) {
            /* the line is all zeros: nothing to read, but time moves on */
            f->w = (f->w + n) % len;
            /* the time slew, sample by sample as 9W9 runs it: in float it stalls
             * ~1 sample short of the target (the step rounds away), and that
             * stalled value is where 9W9's echoes land. It stops at once
             * when it has stalled, so an idle line costs nothing. */
            {
                float dc = f->dcur;
                for (int i = 0; i < n; ++i) {
                    const float nd = dc + (target - dc) * 0.0008f;
                    if (nd == dc)
                        break;
                    dc = nd;
                }
                f->dcur = dc;
            }
            f->wow_ph += d9_inc(0.5f) * (uint32_t)n;
            f->flut_ph += d9_inc(6.1f) * (uint32_t)n;
            return;
        }
    }
    int16_t *buf = f->dbuf;
    const float flen = (float)len;
    const int ping = out_r && f->dl_ping && 2.0f * fm_maxf(f->dcur, target) + 4.0f < flen;
    const float lvl = f->muted & 2u ? 0.0f : f->dl_level;
    int32_t quiet = f->dl_quiet;
    unsigned signal = 0;
    int32_t w = f->w;
    float dcur = f->dcur, lp = f->lp;

    /* Digi and tape share one sample loop; tape adds wow/flutter read mod,
     * darker fdbk/tc, and tanh+HP inside the feedback path. */
    float fdbk, tc, wow_a = 0.0f, flut_a = 0.0f, g = 1.0f, inv_g = 1.0f, hp = 0.0f;
    uint32_t wow_i = 0, flut_i = 0, wp = 0, fp = 0;
    if (!tape) {
        fdbk = f->dl_fdbk;
        tc = 0.06f + f->dl_tone * 0.6f;
    } else {
        /* TAPE: wow (0.5 Hz) and flutter (6.1 Hz) on the read, a darker loop,
         * saturation and a 30 Hz DC block inside it, feedback up to 1.15 */
        const float wear = f->wear;
        const float depth = 0.1f + 1.9f * wear;                  /* x nominal; 1 at wear ~0.5 */
        wow_a = 1.5f * D9_MS * depth;
        flut_a = 0.15f * D9_MS * depth;
        wow_i = d9_inc(0.5f);
        flut_i = d9_inc(6.1f);
        fdbk = f->dl_fdbk * (1.15f / 0.85f);
        tc = (0.06f + f->dl_tone * 0.6f) * (0.6f - 0.3f * wear);
        g = 1.0f + 1.5f * wear;
        inv_g = 1.0f / g;
        wp = f->wow_ph;
        fp = f->flut_ph;
        hp = f->tape_hp;
    }
    for (int i = 0; i < n; ++i) {
        const float x = d9_biquad_tick(&f->dl_hp, in[i]);
        dcur += (target - dcur) * 0.0008f;
        float d = dcur;
        if (tape) {
            wp += wow_i;
            fp += flut_i;
            d = dcur + wow_a * fx_psin(wp) + flut_a * fx_psin(fp);
        }
        const float y = dl_tap(buf, len, flen, w, d);
        const float y2 = ping ? dl_tap(buf, len, flen, w, 2.0f * d) : y;
        signal |= in[i] != 0.0f || y != 0.0f || (out_r && y2 != 0.0f);
        lp += (y2 * fdbk - lp) * tc;
        if (fm_fabsf(lp) < 1e-20f) lp = 0.0f;
        float write = lp;
        if (tape) {
            float s = d9_tanh(lp * g) * inv_g;                   /* tape saturation holds the loop */
            hp += (s - hp) * 0.0042725f;                          /* 30 Hz: no DC latch-up past unity */
            s -= hp;
            write = s;
        }
        int32_t k = sat12_store(&buf[w], x + write);       /* 12-bit, toward zero */
        if (++w >= len) w = 0;
        out[i] += y * lvl;
        if (out_r)
            out_r[i] += y2 * lvl;
        quiet = (k == 0 && in[i] == 0.0f) ? quiet + 1 : 0;
    }
    if (tape) {
        f->wow_ph = wp;
        f->flut_ph = fp;
        f->tape_hp = fm_flush(hp);
    }
    f->w = w;
    f->dcur = dcur;
    f->lp = lp;
    f->dl_quiet = quiet;
    f->dl_signal = (uint8_t)signal;
}

/* Soft-knee glue gain reduction — one body for mono + stereo (same pattern as
 * master soft_ceiling / djf_gsmooth). */
__attribute__((noinline)) static float fx_comp_gr(float over, float slope)
{
    if (over >= 3.0f)
        return -over * slope;
    if (over > -3.0f) {
        const float t = over + 3.0f;
        return -(t * t) * (1.0f / 12.0f) * slope;
    }
    return 0.0f;
}

/* One glue sample: update det/env, return linear gain (mono + stereo). */
__attribute__((noinline)) static float fx_comp_gain(float mag, float thr, float slope, float drel,
                                                    float atk, float rel, float makeup,
                                                    float *det, float *env)
{
    *det = mag > *det ? mag : *det * drel;
    const float in_db = *det > 1e-9f ? 6.0205999f * fm_log2f(*det) : -120.0f;
    const float gr = fx_comp_gr(in_db - thr, slope);
    *env = gr + (*env - gr) * (gr < *env ? atk : rel);
    return fm_db2lin(*env + makeup);
}

/* ===================================================================== */
/* Master: distortion, glue (master_glue), volume                         */
/* ===================================================================== */
void fxbus_process(fxbus_t *f, const float *dry, const float *rev, const float *dly, float *out, int n)
{
    if (n > 256)
        n = 256;
    __builtin_memcpy(out, dry, (unsigned)n * sizeof(float));
    fx_reverb(f, rev, out, 0, n);
    fx_delay(f, dly, out, 0, n);

    if (f->dist_mode >= 1) {
        const float k = f->drive;
        for (int i = 0; i < n; ++i)
            out[i] = dist_one(&f->shape, out[i], k, f->crush_st);
    }
    if (f->comp > 0.001f) {
        const float thr = f->c_thr, slope = f->c_slope, makeup = f->c_makeup;
        const float drel = f->c_drel, atk = f->c_atk, rel = f->c_rel;
        float det = f->comp_det, env = f->comp_env_db;
        for (int i = 0; i < n; ++i) {
            const float in = out[i];
            out[i] = in * fx_comp_gain(fm_fabsf(in), thr, slope, drel, atk, rel, makeup, &det, &env);
        }
        f->comp_det = det;
        f->comp_env_db = env;
    }
    const float vol = f->muted & 4u ? 0.0f : f->volume;
    for (int i = 0; i < n; ++i)
        out[i] *= vol;
}

/* X0X stereo: 9W9's chain on L and R. The distortion runs on each side; the glue compressor reads
 * the louder side and moves both together, so the image holds */
void fxbus_process_st(fxbus_t *f, const float *dry_l, const float *dry_r, const float *rev, const float *dly,
                      float *out_l, float *out_r, int n)
{
    if (n > 256)
        n = 256;
    __builtin_memcpy(out_l, dry_l, (unsigned)n * sizeof(float));
    __builtin_memcpy(out_r, dry_r, (unsigned)n * sizeof(float));
    fx_reverb(f, rev, out_l, out_r, n);
    fx_delay(f, dly, out_l, out_r, n);
    if (f->dist_mode >= 1) {
        const float k = f->drive;
        for (int i = 0; i < n; ++i) {
            out_l[i] = dist_one(&f->shape, out_l[i], k, f->crush_st);
            out_r[i] = dist_one(&f->shape, out_r[i], k, f->crush_str);
        }
    }
    if (f->comp > 0.001f) {
        const float thr = f->c_thr, slope = f->c_slope, makeup = f->c_makeup;
        const float drel = f->c_drel, atk = f->c_atk, rel = f->c_rel;
        float det = f->comp_det, env = f->comp_env_db;
        for (int i = 0; i < n; ++i) {
            const float ml = fm_fabsf(out_l[i]), mr = fm_fabsf(out_r[i]);
            const float g = fx_comp_gain(ml > mr ? ml : mr, thr, slope, drel, atk, rel, makeup, &det, &env);
            out_l[i] *= g;
            out_r[i] *= g;
        }
        f->comp_det = det;
        f->comp_env_db = env;
    }
    const float vol = f->muted & 4u ? 0.0f : f->volume;
    for (int i = 0; i < n; ++i) {
        out_l[i] *= vol;
        out_r[i] *= vol;
    }
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Source-linked 303 TB-3PO mutation/probability-bar semantics across directions. */
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include "sequencer.h"

static pattern_t pat[NPAT];
static unsigned checks, failed, played;
#define VERIFY(c) do { ++checks; if (!(c)) { ++failed; fprintf(stderr, "FAIL line %d: %s\n", __LINE__, #c); } } while(0)
static int on_drum(void*ctx,int kit,int v,float vel){(void)ctx;(void)kit;(void)v;(void)vel;return 1;}
static int on_bass(void*ctx,int b,int note,int accent,int slide,int velocity){(void)ctx;(void)b;(void)note;(void)accent;(void)slide;(void)velocity; return 1; }
static void off_bass(void*ctx,int b){(void)ctx;(void)b;}
static void on_brk(void*ctx,int st,int b,float per,int en){(void)ctx;(void)st;(void)b;(void)per;(void)en;}
static void off_brk(void*ctx){(void)ctx;}
static void out_midi(void*ctx,uint8_t s,uint8_t a,uint8_t b){(void)ctx;(void)s;(void)a;(void)b;}
static void on_step(void*ctx,int part,int step){(void)ctx;(void)step;if(part==TRK_BASS0)++played;}
static const seq_sink_t sink={on_drum,on_bass,off_bass,on_brk,off_brk,out_midi,on_step,0};

static void setup(seq_t *s, int dir, int len)
{
    unsigned p;
    for(p=0;p<NPAT;p++) pattern_init(&pat[p],0x3B0u+p*977u,0x5A1u+p*613u);
    pat[0].bass[0].dir = (uint8_t)dir;
    pat[0].bass[0].len = (uint8_t)len;
    pat[0].bass[0].gen.mutate_bars = 1; /* mutation should track actual bars */
    seq_init(s,pat);
    s->send_clock = 0;
    played=0;
    seq_start(s);
    seq_advance(s,0,&sink);
    VERIFY(played==1);
    VERIFY(s->t[TRK_BASS0].bars==0);
}
static void next(seq_t *s)
{
    unsigned old=played;
    s->t[TRK_BASS0].to_next=0;  /* drive exactly one *real* production event */
    seq_advance(s,0,&sink);
    VERIFY(played==old+1);
    VERIFY(s->t[TRK_BASS0].pos<seq_part_len(s,TRK_BASS0));
}
static void run_direction(int dir, int len, int total)
{
    seq_t s;
    int event;
    unsigned period = (dir==DIR_PINGPONG && len>1) ? 2u*(unsigned)(len-1) : (unsigned)len;
    setup(&s,dir,len);
    for(event=1; event<=total; event++) {
        unsigned expected_bars=(unsigned)(event-1)/(period?period:1);
        VERIFY(s.t[TRK_BASS0].bars==expected_bars);
        if ((unsigned)event<=period) VERIFY(s.mut_rng[0]==0); /* no premature mutation */
        else VERIFY(s.mut_rng[0]!=0); /* TB-3PO mutate did execute at boundary */
        if(event<total) next(&s);
    }
    seq_stop(&s);
    seq_advance(&s,0,&sink);
    seq_start(&s);
    seq_advance(&s,0,&sink);
    VERIFY(s.t[TRK_BASS0].bars==0); /* fresh PLAY starts a fresh logical pass */
    VERIFY(s.t[TRK_BASS0].pos==(dir==DIR_REV?len-1:0));
}
static void resize_random(void)
{
    seq_t s;
    setup(&s,DIR_RANDOM,8);
    next(&s); next(&s); next(&s);
    VERIFY(s.t[TRK_BASS0].bars==0);
    pat[0].bass[0].len=2; /* musician shortens a playing 303 line */
    next(&s);
    VERIFY(s.t[TRK_BASS0].bars==1); /* do not get stuck until the former length */
    VERIFY(s.t[TRK_BASS0].pos<2);
}
static void switch_direction(void)
{
    seq_t s;
    setup(&s,DIR_RANDOM,4);
    next(&s); next(&s);
    {
        unsigned old_bars = s.t[TRK_BASS0].bars;
        int old_pos = s.t[TRK_BASS0].pos;
        pat[0].bass[0].dir=DIR_FWD;
        next(&s);
        VERIFY(s.t[TRK_BASS0].bars==old_bars+(unsigned)(old_pos==3));
        old_bars = s.t[TRK_BASS0].bars;
        pat[0].bass[0].dir=DIR_RANDOM;
        for (int i=1; i<=5; i++) {
            next(&s);
            VERIFY(s.t[TRK_BASS0].bars==old_bars+(unsigned)(i==5));
        }
    }
}
int main(void)
{
    VERIFY(sizeof(seq_track_t)==28); /* preserve tiny embedded per-track RAM allocation */
    run_direction(DIR_FWD,4,17);
    run_direction(DIR_REV,4,17);
    run_direction(DIR_PINGPONG,4,19);
    run_direction(DIR_RANDOM,4,17);
    run_direction(DIR_RANDOM,1,6);
    run_direction(DIR_RANDOM,64,131);
    resize_random();
    switch_direction();
    printf("303 direction logical-bar regression: %u/%u checks\n", checks-failed, checks);
    return failed ? 1 : 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Host proof: Chicago Phaser insert adds moving notches vs dry native303. */
#include <math.h>
#include <stdio.h>
#include <string.h>
#include "bass303.h"
#include "chicago_phaser.h"
#include "chicago_fx.h"

static int fails;
#define CHECK(c, ...)                                                                                                  \
    do {                                                                                                               \
        if (!(c)) {                                                                                                    \
            printf("FAIL " __VA_ARGS__);                                                                               \
            printf("\n");                                                                                              \
            fails++;                                                                                                   \
        }                                                                                                              \
    } while (0)

static float buf[8192];
static float dry[8192];

static void render_note(bass303_t *b, float *out, int n)
{
    int pos = 0;
    bass303_init(b);
    bass303_set(b, BASS303_CUTOFF, 100);
    bass303_set(b, BASS303_RESO, 40);
    bass303_set(b, BASS303_ENVMOD, 0);
    bass303_set(b, BASS303_WAVE, 0);
    bass303_set(b, BASS303_GNAW, 0);
    bass303_set(b, BASS303_BITE, 0);
    bass303_set(b, BASS303_VOLUME, 100);
    bass303_set(b, BASS303_DRIVE, 0);
    bass303_set(b, BASS303_AMPMODE, BASS303_AMP_GATE);
    bass303_note_on_velocity(b, 48, 0, 0, 100);
    while (pos < n) {
        int m = n - pos > 128 ? 128 : n - pos;
        bass303_render(b, out + pos, m);
        pos += m;
    }
}

static double rms_delta(const float *a, const float *b, int n)
{
    double s = 0;
    int i;
    for (i = 0; i < n; i++) {
        double d = (double)a[i] - (double)b[i];
        s += d * d;
    }
    return sqrt(s / (double)n);
}

static void test_supported_flags(void)
{
    CHECK(chi_fx_supported(CHI_FX_PHASER), "Phaser supported");
    CHECK(chi_fx_is_insert(CHI_FX_PHASER), "Phaser is insert");
    CHECK(chi_fx_is_phaser_insert(CHI_FX_PHASER), "Phaser phaser-insert helper");
    CHECK(!chi_fx_is_not_yet(CHI_FX_PHASER), "Phaser not NOT_YET");
    CHECK(strstr(CHI_FX_TYPE_N[CHI_FX_PHASER], "—") == 0, "Phaser label has no em-dash");
}

static void test_map_clears_sends(void)
{
    chicago_fx_out_t o;
    chicago_fx_map(CHI_FX_PHASER, 95, 64, 0, &o);
    CHECK(o.touch == CHI_FX_W_CLEAR_SENDS, "Phaser insert clears sends");
    CHECK(!(o.touch & CHI_FX_W_MX_REV), "Phaser does not set Mix reverb");
    CHECK(!(o.touch & CHI_FX_W_MX_DLY), "Phaser does not set Mix delay");
}

static void test_phaser_changes_pcm(void)
{
    bass303_t b;
    chi_phaser_t ph;
    int n = 4096, skip = 512;
    double delta, delta_hi;
    render_note(&b, dry, n);

    memcpy(buf, dry, (size_t)n * sizeof(float));
    chi_phaser_init(&ph);
    chi_phaser_set(&ph, 95, 64, BASS303_SR); /* Hot Tube-ish */
    chi_phaser_process(&ph, buf + skip, n - skip);
    delta = rms_delta(dry + skip, buf + skip, n - skip);
    CHECK(delta > 1e-4, "Phaser changes waveform (rms delta %g)", delta);

    memcpy(buf, dry, (size_t)n * sizeof(float));
    chi_phaser_init(&ph);
    chi_phaser_set(&ph, 127, 127, BASS303_SR);
    chi_phaser_process(&ph, buf + skip, n - skip);
    delta_hi = rms_delta(dry + skip, buf + skip, n - skip);
    CHECK(delta_hi > delta * 1.02, "higher wet/depth moves PCM more (lo %g hi %g)", delta, delta_hi);

    memcpy(buf, dry, (size_t)n * sizeof(float));
    chi_phaser_init(&ph);
    chi_phaser_process(&ph, buf + skip, n - skip);
    CHECK(memcmp(buf + skip, dry + skip, (size_t)(n - skip) * sizeof(float)) == 0,
          "unset Phaser leaves PCM unchanged");
}

int main(void)
{
    test_supported_flags();
    test_map_clears_sends();
    test_phaser_changes_pcm();
    if (fails) {
        printf("%d FAIL(s)\n", fails);
        return 1;
    }
    printf("PASS chicago_phaser\n");
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* One copy of clip-mode arp pick + rate table.
 * engine.c (-O2) and x0x.c (main_fm1 / -Os) both used smk_clip_keys.h statics;
 * Chicago Arp and clip MIDI share the same helpers — keep a single definition. */
#include "smk_clip_keys.h"

const uint8_t CK_RATE_T[CK_NRATE] = {48, 36, 32, 24, 18, 16, 12, 9, 8, 6, 4, 3, 2};

__attribute__((minsize, noinline)) int ck_arp_pick(const uint8_t *s, uint32_t n, uint32_t order,
                                                    uint32_t oct, uint32_t step, uint32_t rnd)
{
    uint32_t len = n * oct, i = step % len, j;
    if (order == CK_ORD_UPDN || order == CK_ORD_DNUP) {
        j = len > 1u ? step % (2u * len - 2u) : 0u;
        i = j < len ? j : 2u * len - 2u - j;
    }
    if (order == CK_ORD_DOWN || order == CK_ORD_DNUP)
        i = len - 1u - i;
    if (order == CK_ORD_RANDOM)
        i = rnd % len;
    i = s[i % n] + 12u * (i / n);
    return i <= 127u ? (int)i : -1;
}

#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Read-only plan for selected legacy Project PRs; never merge or retarget.

The old generic merger is retired. PR numbers and head SHAs are selection
filters, not local-proof receipts, authority or permission to override checks.
The existing assigned integrator must consume the exact candidate and current
base, validate applicable proof/reviews/permissions, and perform any separately
authorized normal merge through its supported route.

Both the default invocation and --dry-run only read GitHub. --json preserves
machine-readable reports. --print-onetime-setup now explains the retirement;
it makes no claim about current branch protection or a past ruleset unlock.

Usage:
  tools/merge_project_prs.py --dry-run --pr 164
  tools/merge_project_prs.py --json --pr 164 --pr 149
  tools/merge_project_prs.py --head <full-40-character-SHA> --repo OWNER/REPO
"""

from __future__ import annotations

import argparse
import json
import re
import subprocess
import sys
from collections import defaultdict
from dataclasses import asdict, dataclass, field
from typing import Any, Callable, List, Optional, Sequence, Set


DEFAULT_REPO = "gobbajogger/X0X37-for-Loopy-Pro"
TRUNK = "main"
FORBIDDEN_BASES = frozenset({"nightly", "gh-pages"})
FIRMWARE_PREFIXES = ("firmware/",)
LIST_LIMIT = 100
ONETIME_SETUP = """READ-ONLY PLANNER: the generic merge executor is retired.
No merge, retarget, auto-merge, branch or protection write is performed.
Use the current project workflow and existing assigned integration owner.
Stored ruleset-unlock notes and --pr/--head filters are not merge authority.
Reuse current standing authorization; do not request routine owner approval.
Actual required review/check failures and action-specific denials remain binding.
"""


@dataclass
class PullRequest:
    number: int
    title: str
    url: str
    head_ref: str
    base_ref: str
    head_oid: str
    is_draft: bool
    mergeable: str
    merge_state_status: str
    review_decision: str
    auto_merge: Any = None
    files: List[str] = field(default_factory=list)
    check_failures: List[str] = field(default_factory=list)


@dataclass
class Action:
    number: int
    title: str
    url: str
    decision: str
    reason: str
    command: List[str] = field(default_factory=list)
    head_oid: str = ""
    base_ref: str = ""


class GhError(RuntimeError):
    """A required read failed or returned unverified/incomplete data."""


def run_gh(args: Sequence[str], *, check: bool = True) -> subprocess.CompletedProcess:
    # Keep a second guard at the actual subprocess boundary. No caller can turn
    # this helper into the old writer by passing a different gh command.
    if list(args[:2]) != ["pr", "list"]:
        raise GhError("read-only planner refuses non-list gh operations")
    completed = subprocess.run(["gh", *args], capture_output=True, text=True)
    if check and completed.returncode != 0:
        detail = (completed.stderr or completed.stdout or "").strip()
        raise GhError(f"required GitHub PR read failed: {detail or completed.returncode}")
    return completed


def load_open_pulls(repo: str, runner: Callable[..., subprocess.CompletedProcess] = run_gh) -> List[dict]:
    completed = runner([
        "pr", "list", "--repo", repo, "--state", "open", "--limit", str(LIST_LIMIT),
        "--json", "number,title,url,headRefName,baseRefName,headRefOid,isDraft,mergeable,"
        "mergeStateStatus,reviewDecision,autoMergeRequest,statusCheckRollup,files",
    ])
    if completed.returncode != 0:
        detail = (completed.stderr or completed.stdout or "").strip()
        raise GhError(f"required GitHub PR read failed: {detail or completed.returncode}")
    try:
        raw = json.loads(completed.stdout)
    except (TypeError, json.JSONDecodeError) as error:
        raise GhError("required GitHub PR read did not return JSON") from error
    if not isinstance(raw, list) or any(not isinstance(item, dict) for item in raw):
        raise GhError("required GitHub PR read did not return a PR list")
    return raw


def _check_failures(rollup: Any) -> List[str]:
    failures = []
    if not isinstance(rollup, list):
        return failures
    for check in rollup:
        if not isinstance(check, dict):
            continue
        result = (check.get("conclusion") or check.get("state") or "").upper()
        status = (check.get("status") or "").upper()
        if result in {"FAILURE", "ERROR", "TIMED_OUT", "CANCELLED", "ACTION_REQUIRED", "PENDING"} or status in {"IN_PROGRESS", "QUEUED", "PENDING"}:
            name = check.get("name") or check.get("context") or "check"
            failures.append(f"{name}:{result or status}")
    return failures


def parse_pull(raw: dict) -> PullRequest:
    files = raw.get("files")
    if not isinstance(files, list):
        raise GhError("PR file scope is missing; do not infer a safe candidate")
    if not isinstance(raw.get("isDraft"), bool) or isinstance(raw.get("number"), bool) or not isinstance(raw.get("number"), int) or raw["number"] < 1:
        raise GhError("PR identity or draft state is missing")
    paths = [item.get("path") if isinstance(item, dict) else item for item in files]
    if not paths or any(not isinstance(path, str) or not path for path in paths):
        raise GhError("PR file scope is empty or invalid")
    return PullRequest(
        number=raw["number"], title=str(raw.get("title") or ""), url=str(raw.get("url") or ""),
        head_ref=str(raw.get("headRefName") or ""), base_ref=str(raw.get("baseRefName") or ""),
        head_oid=str(raw.get("headRefOid") or ""), is_draft=raw["isDraft"],
        mergeable=str(raw.get("mergeable") or "UNKNOWN"),
        merge_state_status=str(raw.get("mergeStateStatus") or "UNKNOWN"),
        review_decision=str(raw.get("reviewDecision") or ""), auto_merge=raw.get("autoMergeRequest"),
        files=paths, check_failures=_check_failures(raw.get("statusCheckRollup")),
    )


def oid_matches(head_oid: str, proven_heads: Set[str]) -> bool:
    """Legacy selector name; only exact full SHA equality selects a candidate."""
    return bool(re.fullmatch(r"[0-9a-fA-F]{40}", head_oid)) and head_oid.lower() in {h.lower() for h in proven_heads}


def classify(pr: PullRequest, *, proven: bool) -> Action:
    """Report observations, never a verified merge decision. 'proven' is a selector."""
    action = Action(pr.number, pr.title, pr.url, "blocked", "", head_oid=pr.head_oid, base_ref=pr.base_ref)
    if not proven:
        action.decision, action.reason = "skip", "not selected by --pr or exact --head"
    elif not re.fullmatch(r"[0-9a-fA-F]{40}", pr.head_oid):
        action.reason = "full candidate head is unknown"
    elif pr.is_draft:
        action.reason = "draft"
    elif pr.base_ref in FORBIDDEN_BASES:
        action.reason = "shared integration/publication base; use its existing assigned owner"
    elif not pr.head_ref.startswith("cursor/") or (pr.base_ref != TRUNK and not pr.base_ref.startswith("cursor/")):
        action.decision, action.reason = "skip", "outside legacy cursor-to-main planning scope; use the current queue"
    elif any(path.startswith(FIRMWARE_PREFIXES) for path in pr.files):
        action.reason = "firmware/ change needs exact hardware and production authority before main"
    elif pr.mergeable != "MERGEABLE":
        action.reason = f"mergeability is {pr.mergeable or 'UNKNOWN'}"
    elif pr.merge_state_status != "CLEAN":
        action.reason = f"merge state is {pr.merge_state_status or 'UNKNOWN'}"
    elif pr.review_decision in {"CHANGES_REQUESTED", "REVIEW_REQUIRED"}:
        action.reason = f"review state is {pr.review_decision}"
    elif pr.check_failures:
        action.reason = "failed/pending checks need current required-check assessment: " + ", ".join(pr.check_failures)
    elif pr.base_ref != TRUNK:
        action.reason = "stack dependency needs existing integrator reconciliation; never retarget automatically"
    else:
        action.decision = "plan"
        action.reason = "selected candidate for existing integrator review; local proof, fresh base, required checks and authority remain unverified"
    if pr.auto_merge:
        action.reason += "; existing auto-merge setting observed and left unchanged"
    return action


def execute(repo: str, *, dry_run: bool, proven_prs: Set[int], proven_heads: Set[str], runner: Callable[..., subprocess.CompletedProcess] = run_gh) -> List[Action]:
    """Compatibility entrypoint: dry_run=False is also read-only, never a writer."""
    if not proven_prs and not proven_heads:
        raise GhError("pass --pr N and/or --head full-SHA to select a bounded read-only plan")
    if any(not re.fullmatch(r"[0-9a-fA-F]{40}", head) for head in proven_heads):
        raise GhError("--head requires an exact full 40-character commit SHA; prefixes are not proof")
    if any(isinstance(number, bool) or not isinstance(number, int) or number < 1 for number in proven_prs):
        raise GhError("--pr requires positive PR numbers")
    raw = load_open_pulls(repo, runner=runner)
    results, seen_numbers, seen_heads = [], set(), set()
    for item in raw:
        selected = item.get("number") in proven_prs or oid_matches(str(item.get("headRefOid") or ""), proven_heads)
        if not selected:
            continue
        number = item.get("number") if isinstance(item.get("number"), int) else 0
        try:
            pr = parse_pull(item)
            results.append(classify(pr, proven=True))
            seen_numbers.add(pr.number)
            seen_heads.add(pr.head_oid.lower())
        except GhError as error:
            results.append(Action(number, str(item.get("title") or ""), str(item.get("url") or ""), "blocked", str(error)))
            seen_numbers.add(number)
            seen_heads.add(str(item.get("headRefOid") or "").lower())
    for number in sorted(proven_prs - seen_numbers):
        results.append(Action(number, "", "", "unresolved", "selected PR absent from this open-PR read; no completion or merge inferred"))
    for head in sorted({h.lower() for h in proven_heads} - seen_heads):
        results.append(Action(0, "", "", "unresolved", "selected head absent from this open-PR read; no completion or merge inferred", head_oid=head))
    if len(raw) >= LIST_LIMIT:
        for action in results:
            action.reason += f"; inventory capped at {LIST_LIMIT}, absence outside the observed batch remains unknown"
    return sorted(results, key=lambda action: (action.number, action.head_oid))


def format_text(actions: Sequence[Action]) -> str:
    lines = [ONETIME_SETUP.rstrip(), ""]
    counts: dict[str, int] = defaultdict(int)
    for action in actions:
        counts[action.decision] += 1
        lines.append(f"#{action.number} {action.decision}: {action.reason}\n  head={action.head_oid or 'UNKNOWN'} base={action.base_ref or 'UNKNOWN'}\n  {action.title}\n  {action.url}".rstrip())
    lines.append("Read-only observations: " + ", ".join(f"{key}={value}" for key, value in sorted(counts.items())))
    return "\n".join(lines) + "\n"


def _parse_pr_list(values: Sequence[str]) -> Set[int]:
    return {int(part.strip()) for value in values for part in value.split(",") if part.strip()}


def main(argv: Optional[Sequence[str]] = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo", default=DEFAULT_REPO, help="OWNER/REPO (default: %(default)s)")
    parser.add_argument("--dry-run", action="store_true", help="Compatibility flag: every invocation is read-only")
    parser.add_argument("--json", action="store_true", help="Print read-only observations as JSON")
    parser.add_argument("--pr", action="append", default=[], metavar="N", help="Selected PR number, repeatable or comma-separated; not proof")
    parser.add_argument("--head", action="append", default=[], metavar="SHA", help="Selected exact full head SHA, repeatable; not proof")
    parser.add_argument("--print-onetime-setup", action="store_true", help="Explain the retired writer and current owner route")
    args = parser.parse_args(argv)
    if args.print_onetime_setup:
        sys.stdout.write(ONETIME_SETUP)
        return 0
    try:
        actions = execute(args.repo, dry_run=args.dry_run, proven_prs=_parse_pr_list(args.pr), proven_heads={h.strip() for h in args.head if h.strip()})
    except (GhError, OSError, ValueError) as error:
        print(f"merge_project_prs: {error}", file=sys.stderr)
        return 1
    if args.json:
        print(json.dumps([asdict(action) for action in actions], indent=2))
    else:
        sys.stdout.write(format_text(actions))
    # 0 means the read-only report succeeded, never that a PR merged. Blocked
    # independent items are all reported before returning a non-success status.
    return 2 if any(action.decision in {"blocked", "unresolved"} for action in actions) else 0


if __name__ == "__main__":
    sys.exit(main())

/* SPDX-License-Identifier: GPL-3.0-only */
/* Production-source linked MIDI output ownership regression.
 * A live NoteOn must have exactly one NoteOff on the same channel and pitch,
 * including when clock sources, channels and output toggles change while held.
 * This is a host scenario, not a physical MIDI/firmware certification. */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "sequencer.h"

#define TEST_CASES 180
#define STEPS_PER_CASE 90
#define TEST_ASSERT(cond) do { checks++; if (!(cond)) { if (++failures <= 24) \
  fprintf(stderr, "FAIL case=%u op=%u line=%d: %s\n", case_id, op_id, __LINE__, #cond); } } while (0)

typedef struct {
    uint8_t active[16][128];
    unsigned on, off, realtime, duplicate, orphan;
} midi_log_t;
static unsigned checks, failures, case_id, op_id;
static pattern_t patterns[NPAT];
static uint32_t seed;
static uint32_t rnd(void) { seed = seed * 1664525u + 1013904223u; return seed; }
static void midi_out(void *v, uint8_t status, uint8_t note, uint8_t velocity)
{
    midi_log_t *m = v;
    const unsigned ch = status & 15u;
    const unsigned kind = status & 0xf0u;
    if (kind != 0x90u && kind != 0x80u) {
        if (status >= 0xf8u) m->realtime++;
        return;
    }
    if (note >= 128u) { failures++; return; }
    if (kind == 0x90u && velocity) {
        if (m->active[ch][note]) { m->duplicate++; if (failures++ < 24) fprintf(stderr,"DUP case=%u op=%u channel=%u pitch=%u\n",case_id,op_id,ch,note); }
        m->active[ch][note] = 1;
        m->on++;
    } else {
        if (!m->active[ch][note]) { m->orphan++; if (failures++ < 24) fprintf(stderr,"ORPHAN case=%u op=%u channel=%u pitch=%u\n",case_id,op_id,ch,note); }
        m->active[ch][note] = 0;
        m->off++;
    }
}
static int drum(void *v, int kit, int voice, float vel)
{ (void)v; (void)kit; (void)voice; (void)vel; return 1; }
static int bass_on(void *v, int part, int pitch, int accent, int slide, int vel)
{ (void)v; (void)part; (void)pitch; (void)accent; (void)slide; (void)vel;  return 1; }
static void bass_off(void *v, int part) { (void)v; (void)part; }
static void init(seq_t *s)
{
    for (unsigned p = 0; p < NPAT; ++p) pattern_init(&patterns[p], 17u+p, 41u+p);
    for (unsigned b = 0; b < NBASS; ++b) {
        for (unsigned i = 0; i < 16; ++i) {
            bstep_t *st = &patterns[0].bass[b].step[i];
            *st = (bstep_t){(uint8_t)(60u + b * 14u + (i % 3u) * 2u), G_NOTE, 96};
            if (i % 4 == 2) st->flags |= BS_SLIDE;
        }
        patterns[0].bass[b].len = 16;
    }
    seq_init(s, patterns);
    s->send_notes = 1;
    s->send_clock = 1;
}
static void tick(seq_t *s, seq_sink_t *sink, uint32_t k)
{
    while (k) {
        uint32_t next = seq_until_event(s, k);
        TEST_ASSERT(next > 0 && next <= k);
        if (!next || next > k) return;
        seq_advance(s, next, sink);
        k -= next;
    }
}
static void remote(seq_t *s, uint8_t status, unsigned input)
{
    if (seq_clk_take(s, status, input)) seq_midi_rt(s, status);
}
int main(void)
{
    static const uint32_t bufs[] = {1u, 64u, 1024u};
    unsigned total_on = 0, total_off = 0;
    for (case_id = 0; case_id < TEST_CASES; case_id++) {
        midi_log_t log = {0};
        seq_t s;
        init(&s);
        seq_sink_t output = {0};
        output.ctx = &log;
        output.midi = midi_out;
        output.bass_on = bass_on;
        output.bass_off = bass_off;
        output.drum = drum;
        seed = 0x5918ba5eu + case_id * 0x9e3779b9u;
        op_id = 0;
        seq_start(&s);
        tick(&s, &output, 1);
        for (op_id = 1; op_id <= STEPS_PER_CASE; op_id++) {
            uint32_t r = rnd(), op = (r >> 8) % 13u;
            switch (op) {
                case 0: seq_start(&s); break;
                case 1: seq_stop(&s); break;
                case 2: seq_continue(&s); break;
                case 3: remote(&s, 0xfa, (r >> 17) & 1u); break;
                case 4: remote(&s, 0xfb, (r >> 17) & 1u); break;
                case 5: remote(&s, 0xfc, (r >> 17) & 1u); break;
                case 6: for (unsigned k=0;k<1u+((r>>24)&7u);k++) remote(&s,0xf8,(r>>17)&1u); break;
                case 7: s.clk_src = (uint8_t)((s.clk_src + 1u) % 3u); break;
                case 8: s.send_notes = (uint8_t)!s.send_notes; break;
                case 9: s.ch[TRK_BASS0] = (uint8_t)(((r>>22)&1u)?1:2); break;
                case 10: s.ch[TRK_BASS0] = SEQ_CH_OFF; break;
                case 11: s.ch[TRK_BASS0 + 1] = (uint8_t)(((r>>21)&1u)?2:3); break;
                default: s.ch[TRK_BASS0+1] = SEQ_CH_OFF; break;
            }
            tick(&s, &output, bufs[case_id % 3u]);
        }
        /* Always release output even if NoteOut was just disabled or channels changed. */
        op_id = STEPS_PER_CASE + 1u;
        seq_stop(&s); tick(&s, &output, 1u);
        seq_stop(&s); tick(&s, &output, 1u);
        TEST_ASSERT(!s.playing);
        for (unsigned ch = 0; ch < 16u; ch++)
            for (unsigned n = 0; n < 128u; n++)
                TEST_ASSERT(!log.active[ch][n]);
        TEST_ASSERT(log.on == log.off);
        TEST_ASSERT(log.duplicate == 0);
        TEST_ASSERT(log.orphan == 0);
        total_on += log.on; total_off += log.off;
    }
    TEST_ASSERT(total_on > 5);
    TEST_ASSERT(total_on == total_off);
    fprintf(stderr, "seq MIDI lifetime stress: %u/%u assertions %s, %u note-ons, %u note-offs, %u deterministic scenarios\n", checks - failures, checks, failures ? "FAILED" : "PASSED", total_on, total_off, TEST_CASES);
    return failures ? EXIT_FAILURE : EXIT_SUCCESS;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* The inbound recorder (a76, app/smk_inlog.h, editor command 38 INLOG): the word encoding,
 * the filter (APC40 LED notes 0-98 and the Bluetooth edges only), the ring wrap and the copy
 * oldest first.
 *   cc -std=c99 -O2 -Wall -Wextra -Werror -Ifirmware/src tests/smk_inlog_test.c */
#include <assert.h>
#include <stdio.h>
#include "app/smk_inlog.h"

static uint32_t pkt(uint32_t st, uint32_t d1, uint32_t d2) { return (st >> 4) | st << 8 | d1 << 16 | d2 << 24; }

int main(void)
{
    static smk_inlog_t g;
    uint32_t w[SMK_INLOG_N * 2u], i, c;

    /* the size: 64 entries (2026-10-16, before 16). The count goes in one 7-bit byte. */
    assert(SMK_INLOG_N == 64u && SMK_INLOG_N <= 127u && sizeof g.w == 64u * 8u);
    printf("PASS ring size %u entries\n", SMK_INLOG_N);

    /* encoding: src<<24 | status<<16 | d1<<8 | d2 */
    assert(smk_inlog_word(SMK_INLOG_BLE, pkt(0x90, 0x20, 0x45)) == 0x01902045u);
    assert(smk_inlog_word(SMK_INLOG_USB, pkt(0x8E, 0x21, 0x7F)) == 0x008E217Fu);
    assert(smk_inlog_word(SMK_INLOG_NOCELL, pkt(0x9F, 0x27, 0x50)) == 0x039F2750u);
    assert(smk_inlog_word(SMK_INLOG_EDGE, 3u << 24) == 0x02000003u);
    printf("PASS encoding\n");

    /* filter: note on/off for notes 0-98 and the edges only */
    assert(smk_inlog_wanted(SMK_INLOG_BLE, pkt(0x90, 0, 1)));
    assert(smk_inlog_wanted(SMK_INLOG_USB, pkt(0x8F, 98, 0)));
    assert(!smk_inlog_wanted(SMK_INLOG_BLE, pkt(0x90, 99, 1)));
    assert(!smk_inlog_wanted(SMK_INLOG_BLE, pkt(0xB0, 0x10, 5)));   /* knob ring CC */
    assert(!smk_inlog_wanted(SMK_INLOG_USB, pkt(0xF8, 0, 0) & ~0xFu));
    assert(smk_inlog_wanted(SMK_INLOG_EDGE, 0u));
    assert(smk_inlog_wanted(SMK_INLOG_NOCELL, pkt(0x90, 0x20, 0x31)));
    smk_inlog_put(&g, 5u, SMK_INLOG_BLE, pkt(0xB0, 0x10, 5));
    assert(g.n == 0u && g.next == 0u && smk_inlog_copy(&g, w) == 0u);
    assert(smk_inlog_wanted(SMK_INLOG_SMC, pkt(0xE0, 0, 100)));
    assert(smk_inlog_wanted(SMK_INLOG_SMC, pkt(0xBF, 40, 100)));
    assert(smk_inlog_word(SMK_INLOG_SMC, pkt(0xBF, 40, 100)) == 0x04BF2864u);
    printf("PASS filter\n");

    /* an edge goes in only when the link state changes */
    smk_inlog_put(&g, 50u, SMK_INLOG_EDGE, 0u << 24);
    assert(g.n == 0u);
    printf("PASS edge: no change, no entry\n");

    /* fewer than N: all, oldest first */
    smk_inlog_put(&g, 100u, SMK_INLOG_EDGE, 3u << 24);
    smk_inlog_put(&g, 100u, SMK_INLOG_EDGE, 3u << 24);   /* the same state again: no entry */
    smk_inlog_put(&g, 101u, SMK_INLOG_BLE, pkt(0x90, 0x20, 0x45));
    c = smk_inlog_copy(&g, w);
    assert(c == 2u && w[0] == 100u && w[1] == 0x02000003u && w[2] == 101u && w[3] == 0x01902045u);
    printf("PASS fewer than %u entries, oldest first\n", SMK_INLOG_N);

    /* full: 2 + 62 messages fill the ring exactly; nothing is lost yet */
    for (i = 0; i < SMK_INLOG_N - 2u; i++)
        smk_inlog_put(&g, 200u + i, SMK_INLOG_USB, pkt(0x90, i, 1u + i));
    c = smk_inlog_copy(&g, w);
    assert(c == SMK_INLOG_N && g.next == 0u && w[0] == 100u && w[4] == 200u);
    assert(w[2u * SMK_INLOG_N - 2u] == 200u + SMK_INLOG_N - 3u);
    printf("PASS full ring: %u entries, the first one stays\n", SMK_INLOG_N);

    /* wrap: 2 + 90 messages, only the last N stay, oldest first */
    for (i = SMK_INLOG_N - 2u; i < 90u; i++)
        smk_inlog_put(&g, 200u + i, SMK_INLOG_USB, pkt(0x90, i, 1u + i));
    c = smk_inlog_copy(&g, w);
    assert(c == SMK_INLOG_N);
    for (i = 0; i < SMK_INLOG_N; i++) {
        uint32_t k = 90u - SMK_INLOG_N + i;
        assert(w[2u * i] == 200u + k);
        assert(w[2u * i + 1u] == (0x00900000u | k << 8 | (1u + k)));
    }
    printf("PASS ring wrap keeps the last %u entries, oldest first\n", SMK_INLOG_N);

    /* many wraps (300 more messages): the order stays right */
    for (i = 0; i < 300u; i++)
        smk_inlog_put(&g, 1000u + i, SMK_INLOG_BLE, pkt(0x90, 1, i & 0x7Fu));
    c = smk_inlog_copy(&g, w);
    assert(c == SMK_INLOG_N && g.n == SMK_INLOG_N);
    for (i = 0; i < SMK_INLOG_N; i++)
        assert(w[2u * i] == 1000u + 300u - SMK_INLOG_N + i);
    printf("PASS many wraps\n");
    return 0;
}

// SPDX-License-Identifier: MPL-2.0
/* Copyright (C) 2026 M. Geisler (genkigenki/makkuro)
 *
 * Cooperative task table, task queues, semaphores and mutexes for the controller image.
 * No preemption: a task runs until it pends. Interrupt handlers may post (queue, semaphore);
 * they never pend. The "idle context" is poll() on its own stack: it runs each runnable task
 * once and returns to the app's idle loop on core 1 (ctl_os_run_once). */
#include "ctl_port.h"


#define CTL_MAX_TASKS   1   /* btctrler_task_init creates one controller task */
#define CTL_TASKQ_WORDS 64

struct ctl_task {
    const char *name;
    void (*fn)(void *);
    void *arg;
    struct ctl_ctx ctx;
    u32 *stack;
    u32 wake_ms;          /* for os_time_dly / timed pend */
    u8 used, waiting;
    u16 qhead, qtail;     /* message ring (words); a message = [count, type, args...] */
    int q[CTL_TASKQ_WORDS];
};

static struct ctl_task tasks[CTL_MAX_TASKS];
static struct ctl_task *cur;           /* NULL = idle context */
static struct ctl_ctx idle_ctx;

/* Stack size by task name. The SDK uses a name table; this image has
 * only the controller task, so one default is enough. */
#define CTL_TASK_STACK_WORDS 512

static struct ctl_task *find(const char *name)
{
    if (!name) return cur;
    /* This image has one controller task. The SDK's named queue always addresses it. */
    return tasks[0].used ? &tasks[0] : NULL;
}

static void task_trampoline(void)
{
    cur->fn(cur->arg);
    cur->used = 0;                     /* task returned: free its slot */
    ctl_port_ctx_switch(&cur->ctx, &idle_ctx);
}

int task_create(void (*fn)(void *p), void *p, const char *name)
{
    for (int i = 0; i < CTL_MAX_TASKS; i++) {
        struct ctl_task *t = &tasks[i];
        if (t->used) continue;
        memset(t, 0, sizeof(*t));
        t->stack = malloc(CTL_TASK_STACK_WORDS * 4);
        if (!t->stack) return -1;
        t->name = name; t->fn = fn; t->arg = p; t->used = 1; t->waiting = 0;
        ctl_port_ctx_init(&t->ctx, t->stack, CTL_TASK_STACK_WORDS * 4, task_trampoline);
        return 0;
    }
    return -1;
}

int task_kill(const char *name)
{
    struct ctl_task *t = find(name);
    if (!t) return OS_TASK_NOT_EXIST;
    t->used = 0;
    if (t == cur) ctl_port_ctx_switch(&t->ctx, &idle_ctx);
    free(t->stack);
    return 0;
}

const char *os_current_task(void) { return cur ? cur->name : "idle"; }
const char *os_current_task_rom(void) { return os_current_task(); }

/* Give the CPU back to the idle loop until 'ready' says the wait is over. */
static void block_current(void)
{
    if (!cur) { ctl_port_cpu_relax(); return; }   /* idle context (a timer callback): it cannot block, it spins */
    cur->waiting = 1;
    ctl_port_ctx_switch(&cur->ctx, &idle_ctx);
}

static int taskq_count(struct ctl_task *t)
{
    return (int)((t->qhead - t->qtail) & (CTL_TASKQ_WORDS - 1));
}

int os_taskq_post_type(const char *name, int type, int argc, int *argv)
{
    struct ctl_task *t = find(name);
    if (!t) return OS_TASK_NOT_EXIST;
    u32 f = ctl_port_irq_save();
    if (CTL_TASKQ_WORDS - 1 - taskq_count(t) < argc + 2) { ctl_port_irq_restore(f); return OS_Q_FULL; }
    t->q[t->qhead++ & (CTL_TASKQ_WORDS - 1)] = argc + 1;
    t->q[t->qhead++ & (CTL_TASKQ_WORDS - 1)] = type;
    for (int i = 0; i < argc; i++) t->q[t->qhead++ & (CTL_TASKQ_WORDS - 1)] = argv[i];
    t->qhead &= (CTL_TASKQ_WORDS - 1);
    t->waiting = 0;
    ctl_port_irq_restore(f);
    return OS_NO_ERR;
}

int os_taskq_pend(const char *fmt, int *argv, int argc)
{
    (void)fmt;
    struct ctl_task *t = cur;
    if (!t) return OS_Q_EMPTY;
    for (;;) {
        u32 f = ctl_port_irq_save();
        if (taskq_count(t)) {
            int n = t->q[t->qtail++ & (CTL_TASKQ_WORDS - 1)];
            for (int i = 0; i < n; i++) {
                int v = t->q[t->qtail++ & (CTL_TASKQ_WORDS - 1)];
                if (i < argc) argv[i] = v;
            }
            t->qtail &= (CTL_TASKQ_WORDS - 1);
            ctl_port_irq_restore(f);
            return OS_TASKQ;
        }
        ctl_port_irq_restore(f);
        block_current();
    }
}

/* Semaphores and mutexes use the caller's OS_SEM / OS_MUTEX storage
 * (FreeRTOS StaticSemaphore_t in the SDK, much larger than this). */
struct ctl_sem { volatile int count; u32 magic; };
#define SEM_MAGIC 0x53454D31u

int os_sem_create(void *sem, int count)
{
    struct ctl_sem *s = sem; s->count = count; s->magic = SEM_MAGIC; return OS_NO_ERR;
}
int os_sem_post(void *sem)
{
    struct ctl_sem *s = sem;
    u32 f = ctl_port_irq_save(); s->count++; ctl_port_irq_restore(f);
    for (int i = 0; i < CTL_MAX_TASKS; i++) tasks[i].waiting = 0;   /* re-check waiters */
    return OS_NO_ERR;
}
int os_sem_pend(void *sem, int timeout)   /* timeout in ticks (10 ms), 0 = forever */
{
    struct ctl_sem *s = sem;
    u32 end = ctl_ms() + (u32)timeout * (1000u / OS_TICKS_PER_SEC);
    for (;;) {
        u32 f = ctl_port_irq_save();
        if (s->count > 0) { s->count--; ctl_port_irq_restore(f); return OS_NO_ERR; }
        ctl_port_irq_restore(f);
        if (timeout && (s32)(ctl_ms() - end) >= 0) return OS_TIMEOUT;
        if (cur && timeout) cur->wake_ms = end;
        block_current();
    }
}
int os_sem_set(void *sem, int count) { ((struct ctl_sem *)sem)->count = count; return OS_NO_ERR; }
int os_sem_del(void *sem, int block) { (void)sem; (void)block; return OS_NO_ERR; }

int os_mutex_create(void *m) { return os_sem_create(m, 1); }
int os_mutex_pend(void *m, int timeout) { return os_sem_pend(m, timeout); }
int os_mutex_post(void *m) { return os_sem_post(m); }
int os_mutex_del(void *m, int force) { (void)m; (void)force; return OS_NO_ERR; }

void os_time_dly(int ticks)
{
    u32 end = ctl_ms() + (u32)ticks * (1000u / OS_TICKS_PER_SEC);
    while ((s32)(ctl_ms() - end) < 0) {
        if (cur) cur->wake_ms = end;
        block_current();
    }
}

void ctl_os_init(void) { memset(tasks, 0, sizeof(tasks)); cur = NULL; }

/* One pass: timers and the host mailbox, then each task that may be runnable.
 * A task re-checks its own wait condition. */
int ctl_os_run_once(void)
{
    int ran = 0;
    u32 now;
    ctl_timer_poll();
    ctl_host_poll();
    now = ctl_ms();
    for (int i = 0; i < CTL_MAX_TASKS; i++) {
        struct ctl_task *t = &tasks[i];
        if (!t->used) continue;
        if (t->waiting && t->wake_ms && (s32)(now - t->wake_ms) >= 0) t->waiting = 0;
        if (t->waiting) continue;
        t->wake_ms = 0;
        cur = t;
        ctl_port_ctx_switch(&idle_ctx, &t->ctx);
        cur = NULL;
        ran = 1;
    }
    return ran;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* BF-007: loading an older sound revision must remap Bass Drum PAN motion,
 * not just the stored static PAN parameter. Mock NOR, real compression/storage. */
#define main project_stage_existing_main
#include "project_stage_test.c"
#undef main

static void legacy_case(uint8_t rev, uint8_t pan909, uint8_t pan808)
{
    lane_t *a, *b;
    fixture("legacy 909/808 BD PAN motion keeps parameter after import");
    proj.set.snd_rev = rev;
    proj.sound.v[T_909][0][pan909] = 73;
    proj.sound.v[T_808][0][pan808] = 81;
    a = &proj.arr.lane[0];
    b = &proj.arr.lane[1];
    memset(a, 0, sizeof *a);
    memset(b, 0, sizeof *b);
    a->used = b->used = 1;
    a->t = T_909;
    b->t = T_808;
    a->part = PART_909;
    b->part = PART_808;
    a->v = b->v = 0;
    a->i = pan909;
    b->i = pan808;
    memset(a->val, MOT_NONE, sizeof a->val);
    memset(b->val, MOT_NONE, sizeof b->val);
    a->val[0] = 73;
    b->val[0] = 81;
    REQUIRE(project_save() == 0);
    memset(stored_known, 0, sizeof stored_known);
    REQUIRE(project_load_stage() == 0);
    CHECK(project_stage.sound.v[T_909][0][10] == 73);
    CHECK(project_stage.sound.v[T_808][0][9] == 81);
    CHECK(project_stage.arr.lane[0].i == 10);
    CHECK(project_stage.arr.lane[1].i == 9);
    CHECK(project_stage.arr.lane[0].val[0] == 73);
    CHECK(project_stage.arr.lane[1].val[0] == 81);
}

int main(void)
{
    /* Before rev3 909 BD PAN=8; before rev4 808 BD PAN=7.
     * Rev3 already moved 909 to index 10; rev4 already moved both. */
    legacy_case(2, 8, 7);
    legacy_case(3, 10, 7);
    legacy_case(PROJ_SND_REV, 10, 9);
    printf("BF-007 BD PAN migration: %u checks, %u failures\n", checks, failures);
    return failures ? 1 : 0;
}

